//! Behaviors first seen in real collector output (the GOAD lab), reproduced in
//! `testdata/sdprop` (generated by `scripts/gen_sdprop_fixture.py`).

use std::path::PathBuf;

use pathwarden_core::findings::{self, Context, Finding, RuleSettings};
use pathwarden_core::{load, time, LoadOptions};

fn run() -> (Vec<Finding>, Option<i64>) {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/sdprop");
    let (g, stats) = load(&[dir], &LoadOptions::default()).unwrap();
    let settings = RuleSettings {
        now: stats.collected_at.unwrap(),
        ..RuleSettings::default()
    };
    let all = findings::evaluate(&Context::new(&g, &stats.trusts, &settings), &[]);
    (all, stats.collected_at)
}

fn titles(all: &[Finding], rule: &str) -> Vec<String> {
    let mut t: Vec<String> = all
        .iter()
        .filter(|f| f.rule == rule)
        .map(|f| f.title.clone())
        .collect();
    t.sort();
    t
}

#[test]
fn collection_time_comes_from_file_names() {
    let (_, collected) = run();
    assert_eq!(time::format_unix(collected.unwrap()), "2024-04-10 08:36");
}

#[test]
fn sdprop_copies_are_reported_once_on_adminsdholder() {
    let (all, _) = run();
    let pw003 = titles(&all, "PW-003");
    assert_eq!(
        pw003,
        [
            "BOB@SDP.LOCAL has GenericWrite, WriteDacl on DC01.SDP.LOCAL",
            "MALLORY@SDP.LOCAL has GenericAll on ADMINSDHOLDER@SDP.LOCAL",
        ]
    );
    let holder = all
        .iter()
        .find(|f| f.title.contains("ADMINSDHOLDER"))
        .unwrap();
    assert!(
        holder
            .summary
            .contains("onto 3 protected accounts and groups"),
        "{}",
        holder.summary
    );
}

#[test]
fn several_rights_on_one_object_are_one_finding() {
    let (all, _) = run();
    let dc: Vec<&Finding> = all
        .iter()
        .filter(|f| f.rule == "PW-003" && f.title.contains("DC01"))
        .collect();
    assert_eq!(dc.len(), 1);
    // Both fixes are in the one ticket.
    assert!(dc[0].remediation.contains("GenericWrite") && dc[0].remediation.contains("WriteDacl"));
}
